    int max_exp_needed = 0;
    for (int i = 0; i < N; i++) {
        if (tools[i].r > max_exp_needed) max_exp_needed = tools[i].r;
    }
    // We might need a bit more than max_exp_needed but cap at D (reasonable bound)
    int exp_cap = D < 1000 ? D : 1000; 
    if (max_exp_needed > exp_cap) exp_cap = max_exp_needed + 10;

    int visited[MAXD+1][exp_cap+1];
    for (int i = 0; i <= D; i++)
        for (int j = 0; j <= exp_cap; j++)
            visited[i][j] = INT_MAX;

    // Priority queue using array (simple approach for limits)
    // We'll implement a simple BFS-like Dijkstra with manual queue
    State pq[MAXD * (exp_cap+1)];
    int pq_size = 0;

    // push initial state
    pq[pq_size].d = D;
    pq[pq_size].exp = 0;
    pq[pq_size].strikes = 0;
    pq_size++;
    visited[D][0] = 0;

    int front = 0;
    while (front < pq_size) {
        State cur = pq[front++];
        int d = cur.d;
        int exp = cur.exp;
        int strikes = cur.strikes;

        if (visited[d][exp] < strikes) continue;

        // Try each tool
