            if (exp >= tools[i].r) {
                int new_d = d - tools[i].a;
                if (new_d < 0) new_d = 0;
                int new_exp = exp + tools[i].e;
                if (new_exp > exp_cap) new_exp = exp_cap;
                int new_strikes = strikes + 1;

                if (new_strikes < visited[new_d][new_exp]) {
                    visited[new_d][new_exp] = new_strikes;
                    pq[pq_size].d = new_d;
                    pq[pq_size].exp = new_exp;
                    pq[pq_size].strikes = new_strikes;
                    pq_size++;
                }
            }
        }
    }

    int answer = INT_MAX;
