typedef long long ll;

typedef struct {
    ll a, e, r;
} Tool;

int cmp_r(const void *p, const void *q) {
    const Tool *x = (const Tool *)p;
    const Tool *y = (const Tool *)q;
    if (x->r < y->r) return -1;
    if (x->r > y->r) return 1;
    return 0;
}

ll minll(ll a, ll b) { return a < b ? a : b; }
ll maxll(ll a, ll b) { return a > b ? a : b; }

int main(void) {
    int N;
    ll D;
    if (scanf("%d %lld", &N, &D) != 2) return 0;

    Tool *tools = (Tool *)malloc(sizeof(Tool) * N);
    for (int i = 0; i < N; i++) {
        scanf("%lld %lld %lld", &tools[i].a, &tools[i].e, &tools[i].r);
    }

    qsort(tools, N, sizeof(Tool), cmp_r);

    /* dp[x] = maximum experience reachable in exactly x strikes,
       considering all currently unlocked tools transitions.
       We only need up to N unlock steps plus some extra strikes after
       the best tool is available. */
    ll *best_exp_at = (ll *)malloc(sizeof(ll) * (N + 1));
    for (int i = 0; i <= N; i++) best_exp_at[i] = -1;
    best_exp_at[0] = 0;

    ll answer = LLONG_MAX;

    /* prefix best damage among unlocked tools */
    ll best_a = 0, best_e = 0;

    int idx = 0;

    /* We process unlock thresholds in increasing r.
       For each reachable strike count s, if exp >= r, tools become usable. */
    for (int strikes = 0; strikes <= N; strikes++) {
        if (best_exp_at[strikes] < 0) continue;

        ll cur_exp = best_exp_at[strikes];

        while (idx < N && tools[idx].r <= cur_exp) {
            if (tools[idx].a > best_a) {
                best_a = tools[idx].a;
                best_e = tools[idx].e;
            } else if (tools[idx].a == best_a && tools[idx].e > best_e) {
                best_e = tools[idx].e;
            }
            idx++;
        }

        if (best_a > 0) {
            /* From this point, using the currently best-damage unlocked tool
               can finish the tree in:
               strikes + ceil(D / best_a)
               but we can do better if future unlocks enable stronger tools.
               Still, this is a valid upper bound. */
            ll need = (D + best_a - 1) / best_a;
            answer = minll(answer, need);
        }

        if (strikes == N) continue;

        /* Try one more strike with any unlocked tool.
           To maximize future possibilities, only experience matters.
           Using the unlocked tool with maximum e is sufficient for reachability DP. */
        ll max_e = 0;
        for (int j = 0; j < idx; j++) {
            if (tools[j].e > max_e) max_e = tools[j].e;
        }
        if (max_e > 0) {
            best_exp_at[strikes + 1] = maxll(best_exp_at[strikes + 1], cur_exp + max_e);
        }
    }

    /* More accurate computation:
       We simulate minimum strikes to unlock better tools using max experience gain.
       Let dp[k] = max experience after k preparatory strikes.
       Once some tool is unlocked, total strikes can be:
       k + ceil(D / best_damage_unlocked_at_k)
    */
    ll *dp = (ll *)malloc(sizeof(ll) * (N + 1));
    for (int i = 0; i <= N; i++) dp[i] = -1;
    dp[0] = 0;

    ll unlocked_best_damage = 0;
    ll unlocked_best_exp = 0;
    idx = 0;

    for (int k = 0; k <= N; k++) {
        if (dp[k] < 0) continue;

        while (idx < N && tools[idx].r <= dp[k]) {
            unlocked_best_damage = maxll(unlocked_best_damage, tools[idx].a);
            unlocked_best_exp = maxll(unlocked_best_exp, tools[idx].e);
            idx++;
        }

        if (unlocked_best_damage > 0) {
            ll total = k + (D + unlocked_best_damage - 1) / unlocked_best_damage;
            answer = minll(answer, total);
        }

        if (k < N && unlocked_best_exp > 0) {
            dp[k + 1] = maxll(dp[k + 1], dp[k] + unlocked_best_exp);
        }
    }

    /* If nothing was ever unlocked, impossible under given constraints.
       Problem statement usually guarantees solvable instances, but handle anyway. */
    if (answer == LLONG_MAX) {
        printf("-1\n");
    } else {
        printf("%lld\n", answer);
    }

    free(dp);
    free(best_exp_at);
    free(tools);
    return 0;
}

