    }

    // dp[durability] = max experience we can have with minimum strikes
    // We'll store pairs: (strikes, experience)
    vector<pair<int, int>> dp(D + 1, {INF, -INF});
    dp[D] = {0, 0};

    int answer = INF;

    // Use Dijkstra-like BFS over durability
    using State = tuple<int, int, int>; // strikes, -experience, durability
    priority_queue<State, vector<State>, greater<State>> pq;
    pq.push({0, 0, D});

    while (!pq.empty()) {
        auto [strikes, negExp, dur] = pq.top();
        pq.pop();
        int exp = -negExp;

        if (strikes != dp[dur].first || exp != dp[dur].second) continue;

        for (int i = 0; i < N; i++) {
            if (exp >= r[i]) {
                int ndur = max(0, dur - a[i]);
                int nexp = exp + e[i];
                int nstrikes = strikes + 1;

