                    answer = min(answer, nstrikes);
                    continue;
                }

                if (nstrikes < dp[ndur].first || 
                    (nstrikes == dp[ndur].first && nexp > dp[ndur].second)) {
                    dp[ndur] = {nstrikes, nexp};
                    pq.push({nstrikes, -nexp, ndur});
                }
            }
        }
    }

    cout << answer << "\n";
