using ll = long long;
const ll INF = (1LL << 60);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    ll D;
    cin >> N >> D;

    struct Tool {
        ll a, e, r;
    };
    vector<Tool> tools(N);
    for (int i = 0; i < N; ++i) {
        cin >> tools[i].a >> tools[i].e >> tools[i].r;
    }

    // Sort by required experience.
    sort(tools.begin(), tools.end(), [](const Tool& x, const Tool& y) {
        return x.r < y.r;
    });

    // dp[i] = maximum total damage achievable in exactly i strikes
    // while respecting tool availability by accumulated experience.
    // Since experience only increases, after i strikes the maximum possible
    // experience is enough to determine which tools are usable.
    //
    // We process reachable strike counts and relax using currently available tools.
    // To know availability, we track for each strike count the maximum experience
    // among states that achieve dp damage? That is not sufficient in general.
    //
    // Instead, use DP on experience milestones induced by tool requirements.
    // Let states be tool-unlock levels after sorting by r.
    // For each level k, all tools [0..k-1] are available if current exp >= r[k-1].
    //
    // We compute minimal strikes to reach each unlock threshold.
    // dist[k] = minimum strikes needed to get experience >= tools[k].r
    // Starting exp = 0.
    //
    // To minimize total strikes to deal D damage:
    // before each new unlock, best available tool for damage is among unlocked ones.
    // To reach more experience, best tool for experience is among unlocked ones.
    //
    // We can model transitions between thresholds:
    // from current unlocked set, using any unlocked tool repeatedly.
    // If unlocked tools have maxExp = max e, then minimum extra strikes to reach next
    // threshold is ceil((next_r - cur_exp_max_reachable)/maxExp), but exact current exp
    // matters. We therefore maintain maximum experience achievable with exactly s strikes,
    // compressed by thresholds.
    //
    // Since requirements only matter at threshold values, let reqs = unique {0, r_i}.
    vector<ll> reqs = {0};
    for (auto &t : tools) reqs.push_back(t.r);
    sort(reqs.begin(), reqs.end());
    reqs.erase(unique(reqs.begin(), reqs.end()), reqs.end());

    int M = (int)reqs.size();

    // dp[j] = minimum strikes to reach experience at least reqs[j]
    vector<ll> dp(M, INF);
    dp[0] = 0;

    for (int j = 0; j < M; ++j) {
        if (dp[j] == INF) continue;
        ll curExp = reqs[j];

        ll bestE = -1, bestA = -1;
        for (auto &t : tools) {
            if (t.r <= curExp) {
                bestE = max(bestE, t.e);
                bestA = max(bestA, t.a);
            } else break;
        }

        if (bestA == -1) continue; // no usable tool

        // If we stop here and only use the best damage tool, compute answer.
        ll need = (D + bestA - 1) / bestA;
        ll ans = dp[j] + need;

        static ll globalAns = INF;
        globalAns = min(globalAns, ans);

        // Transition to higher experience thresholds using best experience tool.
        if (bestE > 0) {
            for (int nj = j + 1; nj < M; ++nj) {
                if (reqs[nj] <= curExp) {
                    dp[nj] = min(dp[nj], dp[j]);
                } else {
                    ll add = (reqs[nj] - curExp + bestE - 1) / bestE;
                    dp[nj] = min(dp[nj], dp[j] + add);
                }
            }
        }

        if (j == M - 1) {
            cout << globalAns << '\n';
            return 0;
        }
    }

    ll finalAns = INF;
    for (int j = 0; j < M; ++j) {
        if (dp[j] == INF) continue;
        ll curExp = reqs[j];
        ll bestA = -1;
        for (auto &t : tools) {
            if (t.r <= curExp) bestA = max(bestA, t.a);
            else break;
        }
        if (bestA == -1) continue;
        finalAns = min(finalAns, dp[j] + (D + bestA - 1) / bestA);
    }

    cout << finalAns << '\n';
    return 0;
}

