            for (int i = 0; i < N; i++) {
                if (exp >= r[i]) {
                    int newDur = dur - a[i];
                    if (newDur <= 0) { System.out.println(d + 1); return; }
                    int newExp = Math.min(exp + e[i], maxR);
                    if (dist[newDur][newExp] > d + 1) {
                        dist[newDur][newExp] = d + 1;
                        queue.add(new int[]{newDur, newExp});
                    }
                }
            }
        }
