import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Tool {
        long a, e, r;
        Tool(long a, long e, long r) {
            this.a = a;
            this.e = e;
            this.r = r;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        long D = fs.nextLong();

        Tool[] tools = new Tool[N];
        long maxR = 0;
        for (int i = 0; i < N; i++) {
            long a = fs.nextLong();
            long e = fs.nextLong();
            long r = fs.nextLong();
            tools[i] = new Tool(a, e, r);
            maxR = Math.max(maxR, r);
        }

        Arrays.sort(tools, Comparator.comparingLong(t -> t.r));

        // dp[x] = maximum damage achievable in exactly current number of strikes
        // while having exactly x experience after those strikes.
        // We only need experience states up to maxR, because once exp >= maxR,
        // every tool is available forever.
        int M = (int) Math.min(maxR, 200000L); // placeholder, overridden below safely

        if (maxR > Integer.MAX_VALUE - 5) {
            // If requirements are extremely large, compressing all states is impossible.
            // But in typical competitive constraints, maxR fits int.
            // We still guard against overflow.
            throw new RuntimeException("Requirement too large");
        }
        M = (int) maxR;

        long[] dp = new long[M + 1];
        Arrays.fill(dp, -1);
        dp[0] = 0;

        int ptr = 0;
        long bestAAll = 0;
        long bestEAll = 0;

        // Precompute best damage among tools with positive exp gain once all unlocked.
        long bestUnlockedDamage = 0;
        long bestUnlockedExp = 0;

        for (int steps = 0; ; steps++) {
            // Check if tree already can be felled in current number of strikes.
            for (int x = 0; x <= M; x++) {
                if (dp[x] >= D) {
                    System.out.println(steps);
                    return;
                }
            }

            // Update best available tools for each exp threshold sweep.
            while (ptr < N && tools[ptr].r <= 0) {
                if (tools[ptr].a > bestAAll) {
                    bestAAll = tools[ptr].a;
                    bestEAll = tools[ptr].e;
                }
                ptr++;
            }

            long[] ndp = new long[M + 1];
            Arrays.fill(ndp, -1);

            ptr = 0;
            long bestDamage = 0;
            long bestExpGainForBestDamage = 0;

            // For each exp state, maintain best currently usable tool by damage.
            for (int x = 0; x <= M; x++) {
                while (ptr < N && tools[ptr].r <= x) {
                    if (tools[ptr].a > bestDamage) {
                        bestDamage = tools[ptr].a;
                        bestExpGainForBestDamage = tools[ptr].e;
                    } else if (tools[ptr].a == bestDamage && tools[ptr].e > bestExpGainForBestDamage) {
                        bestExpGainForBestDamage = tools[ptr].e;
                    }
                    ptr++;
                }

                if (dp[x] < 0 || bestDamage == 0) continue;

                long nx = x + bestExpGainForBestDamage;
                if (nx > M) nx = M;
                ndp[(int) nx] = Math.max(ndp[(int) nx], dp[x] + bestDamage);
            }

            boolean progressed = false;
            for (int i = 0; i <= M; i++) {
                if (ndp[i] > dp[i]) progressed = true;
            }

            dp = ndp;

            // If after reaching maxR, we can use the globally best damage tool forever.
            // Since state M represents "experience >= maxR", transitions above already work.

            // If no progress is possible, impossible to fell the tree.
            boolean any = false;
            for (long v : dp) {
                if (v >= 0) {
                    any = true;
                    break;
                }
            }
            if (!any || !progressed) {
                System.out.println(-1);
                return;
            }
        }
    }
